Run it:
```js
import assert from "node:assert/strict";
const request = /^(?<method>GET|POST|PUT|DELETE) (?<path>\S+) HTTP\/\d\.\d (?<status>\d{3}) (?<bytes>\d+)$/;
const m = "GET /docs/index.html HTTP/1.1 404 512".match(request);
assert.deepEqual({ ...m.groups }, { method: "GET", path: "/docs/index.html", status: "404", bytes: "512" });
assert.equal("FETCH /x HTTP/1.1 200 5".match(request), null);
assert.equal("GET /x HTTP/1.1 20 5".match(request), null);
// the lastIndex trap, demonstrated:
const digits = /\d+/g;
assert.deepEqual([digits.test("a1"), digits.test("a1")], [true, false]);
console.log(m.groups);
```
